const supersedeQueuedDeployments = `-- name: SupersedeQueuedDeployments :many
UPDATE deployments SET status = 'superseded', superseded_by_id = $2,
    finished_at = now(), updated_at = now()
WHERE resource_id = $1 AND status = 'queued' AND trigger = 'webhook' AND id <> $2
RETURNING id
`

type SupersedeQueuedDeploymentsParams struct {
	ResourceID     int64
	SupersededByID *int64
}

// Coalescing (§3.4): a queued webhook deployment for the same application
// is superseded by a newer one; an already leased/running deployment is
// never coalesced.
func (q *Queries) SupersedeQueuedDeployments(ctx context.Context, arg SupersedeQueuedDeploymentsParams) ([]int64, error) {
	rows, err := q.db.Query(ctx, supersedeQueuedDeployments, arg.ResourceID, arg.SupersededByID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []int64
	for rows.Next() {
		var id int64
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		items = append(items, id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
